export function formatInvoice(i: Invoice) { return `${i.id}:${i.amountCents}` }

// paymentProcessor.ts
import { Invoice } from "./billing"
export function charge(invoice: Invoice) {
  // callers rely on metadata shape and mutate it directly
  processPayment(invoice.metadata.gatewayId, invoice.amountCents)
