// Version A
// Service directly imports concrete PaymentGateway and constructs it
import { PaymentGateway } from './gateways/stripe'
export class BillingService {
  private gateway = new PaymentGateway(process.env.STRIPE_KEY!)
  charge(i: any) { return this.gateway.charge(i) }
}

// Version B
// Service depends on an interface and receives a gateway implementation via constructor
export interface IPaymentGateway { charge(invoice: any): Promise<any> }
export class BillingServiceV2 { constructor(private gateway: IPaymentGateway) {}
  charge(i: any) { return this.gateway.charge(i) }
}
